            this.runtime.off('ANIMATIONS_FORCE_STEP', frameHandler);
            this.runtime.off('ANIMATIONS_FORCE_SPECIFIC_STEP', forceSpecificStepHandler);
            this.runtime.off('PROJECT_STOP_ALL', stopAllHandler);
